const event = $input.first().json.body;
if (!event || event.schemaVersion !== 1 || event.event !== 'lead.created' || !/^lead_[a-f0-9]{32}$/.test(event.id || '') || !Number.isFinite(Date.parse(event.createdAt))) throw new Error('Invalid lead event');
const f = event.fields;
if (!f || typeof f !== 'object' || Array.isArray(f)) throw new Error('Invalid fields');
const limits = {name:80,email:120,business:100,industry:100,interest:100,challenge:1800,preferredContact:20,phone:25,teamSize:5,timeSpent:100,tools:200};
const clean = {};
for (const [key,max] of Object.entries(limits)) { if (typeof (f[key] ?? '') !== 'string' || (f[key] || '').length > max) throw new Error('Invalid '+key); clean[key] = (f[key] || '').trim(); }
for (const key of ['name','email','business','industry','interest','challenge','preferredContact']) if (!clean[key]) throw new Error('Missing '+key);
if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(clean.email) || !['email','whatsapp','phone'].includes(clean.preferredContact)) throw new Error('Invalid contact');
if (['phone','whatsapp'].includes(clean.preferredContact) && !clean.phone) throw new Error('Phone required');
return [{json:{schemaVersion:1,event:'lead.created',id:event.id,createdAt:event.createdAt,source:'autixai-website',fields:clean}}];
